-- Queue 189 Lin-approved records in the protected central game_words catalog as inactive Paid content.
-- Free 200 and every public/runtime entitlement remain unchanged. No Paid runtime path is added.

begin;

lock table public.game_words in share row exclusive mode;

do $precheck$
begin
  if (select count(*) from public.game_words where status='active') <> 200
     or (select count(*) from public.game_words where status='active' and access_tier='guest') <> 100
     or (select count(*) from public.game_words where status='active' and access_tier='login') <> 100
     or (select md5(string_agg(record_hash, E'\n' order by content_key collate "C")) from public.game_words where status='active') <> '4be1d6442da1c2980b1e084aafc45394' then
    raise exception 'Free 200 precheck failed; Paid queue mutation stopped';
  end if;
  if exists(select 1 from public.game_words where status='queued' or access_tier='paid') then
    raise exception 'Paid queue already exists; idempotent re-run not authorized';
  end if;
end
$precheck$;

