  content_key text, word text, en text, zh text, level text, category text, type text, subcategory text,
  syls jsonb, spelling_th text, reading_th text, audio_status text, rank integer, access_tier text,
  catalog_version text, record_hash text, canonical_record jsonb
);

do $payload_check$
begin
  if (select count(*) from _paid_queue_189) <> 189
     or (select count(distinct content_key) from _paid_queue_189) <> 189
     or (select count(*) from _paid_queue_189 where level='初') <> 183
     or (select count(*) from _paid_queue_189 where level='中') <> 6
     or exists(select 1 from _paid_queue_189 where access_tier <> 'paid' or catalog_version <> 'paid-queue-189-v1')
     or (select md5(string_agg(record_hash, E'\n' order by content_key collate "C")) from _paid_queue_189) <> '2719d0ca5647c7b7ad52c5d12ac421c8' then
    raise exception 'Paid queue payload invariant failed';
  end if;
  if exists(select 1 from public.game_words g join _paid_queue_189 p using(content_key) where g.status='active') then
    raise exception 'Paid queue collides with active Free content_key';
  end if;
end
$payload_check$;

alter table public.game_words drop constraint if exists game_words_status_check;
alter table public.game_words add constraint game_words_status_check check(status in('active','queued','history'));
alter table public.game_words drop constraint if exists game_words_access_tier_check;
alter table public.game_words add constraint game_words_access_tier_check check(access_tier is null or access_tier in('guest','login','paid'));

drop index if exists public.uq_game_words_word_level;
create index if not exists idx_game_words_word_level on public.game_words(word,level);

insert into public.game_words(
  content_key,word,en,zh,level,category,syls,reading_th,read_syls,rank,spelling_th,audio_status,type,subcategory,
  access_tier,catalog_version,record_hash,canonical_record,status,updated_at
)
select content_key,word,en,zh,level,category,syls,reading_th,null,rank,spelling_th,audio_status,type,subcategory,
       access_tier,catalog_version,record_hash,canonical_record,'queued',now()
from _paid_queue_189
on conflict(content_key) do update set
  word=excluded.word,en=excluded.en,zh=excluded.zh,level=excluded.level,category=excluded.category,syls=excluded.syls,
  reading_th=excluded.reading_th,read_syls=excluded.read_syls,rank=excluded.rank,spelling_th=excluded.spelling_th,
  audio_status=excluded.audio_status,type=excluded.type,subcategory=excluded.subcategory,access_tier=excluded.access_tier,
  catalog_version=excluded.catalog_version,record_hash=excluded.record_hash,canonical_record=excluded.canonical_record,
  status='queued',updated_at=now()
where public.game_words.status='history';

create index if not exists idx_game_words_paid_queue_level_rank
  on public.game_words(level,rank) where status='queued' and access_tier='paid';

alter table public.game_words enable row level security;
revoke all on table public.game_words from public,anon,authenticated;
grant select on table public.game_words to service_role;

do $postcheck$
begin
  if (select count(*) from public.game_words where status='active') <> 200
     or (select count(*) from public.game_words where status='active' and access_tier='guest') <> 100
     or (select count(*) from public.game_words where status='active' and access_tier='login') <> 100
     or (select count(*) from public.game_words where status='queued' and access_tier='paid') <> 189
     or (select count(*) from public.game_words where status='queued' and access_tier='paid' and level='初') <> 183
     or (select count(*) from public.game_words where status='queued' and access_tier='paid' and level='中') <> 6
     or (select count(*) from public.game_words where status='queued' and access_tier='paid' and canonical_record is null) <> 0
     or (select md5(string_agg(record_hash, E'\n' order by content_key collate "C")) from public.game_words where status='queued' and access_tier='paid') <> '2719d0ca5647c7b7ad52c5d12ac421c8'
     or (select md5(string_agg(record_hash, E'\n' order by content_key collate "C")) from public.game_words where status='active') <> '4be1d6442da1c2980b1e084aafc45394' then
    raise exception 'Paid queue postcheck failed';
  end if;
  if has_table_privilege('anon','public.game_words','select') or has_table_privilege('authenticated','public.game_words','select') then
    raise exception 'browser role can read protected vocabulary catalog';
  end if;
end
$postcheck$;

notify pgrst,'reload schema';
commit;
